const C={ink:'#173a50',muted:'#60788a',edge:'#8aa7b7',blue:'#4789b0',aqua:'#ddedf5',gold:'#d3af59',cream:'#fff0be',gray:'#f2f6f9'};
const esc=x=>String(x??'').replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;').replaceAll('"','&quot;');
const text=(x,y,s,size=15,anchor='middle',color=C.ink,weight=400)=>`<text x="${x}" y="${y}" font-family="Arial,sans-serif" font-size="${size}" text-anchor="${anchor}" fill="${color}" font-weight="${weight}">${esc(s)}</text>`;
const path=(d,fill='none',stroke=C.edge,w=2)=>`<path d="${d}" fill="${fill}" stroke="${stroke}" stroke-width="${w}" stroke-linecap="round" stroke-linejoin="round"/>`;
const rect=(x,y,w,h,fill=C.gray,rx=7,stroke=C.edge)=>`<rect x="${x}" y="${y}" width="${w}" height="${h}" rx="${rx}" fill="${fill}" stroke="${stroke}" stroke-width="1.5"/>`;
const circle=(x,y,r,fill,stroke='none')=>`<circle cx="${x}" cy="${y}" r="${r}" fill="${fill}" stroke="${stroke}" stroke-width="1.5"/>`;
const arrow=(a,b,c,d,color=C.blue)=>{const t=Math.atan2(d-b,c-a);return path(`M${a} ${b}L${c} ${d}`,'none',color)+path(`M${c-7*Math.cos(t-.55)} ${d-7*Math.sin(t-.55)}L${c} ${d}L${c-7*Math.cos(t+.55)} ${d-7*Math.sin(t+.55)}`,'none',color);};
function wrap(s,max=50){const a=[];let line='';for(const word of String(s??'').split(/\s+/)){if((line+' '+word).trim().length>max&&line){a.push(line);line=word;}else line=(line+' '+word).trim();}if(line)a.push(line);return a;}
const lines=(x,y,s,max=25,size=14,color=C.muted)=>wrap(s,max).map((t,i)=>text(x,y+i*(size+5),t,size,'middle',color)).join('');
function vessel(x,y,w=75,h=105,fill=C.aqua){return rect(x,y,w,h,'#fcfeff',9)+rect(x+5,y+h*.53,w-10,h*.4,fill,4,'none')+path(`M${x+10} ${y+9}V${y+h-8}`,'none','white',4);}
function powder(x,y,color=C.gold){return [0,1,2,3,4,5,6].map(i=>circle(x+(i%4)*10,y-Math.floor(i/4)*9,4,color,C.edge)).join('');}
function crystal(x,y){return path(`M${x} ${y}l12 -19l18 9l-4 26l-18 3Z`,C.cream,C.gold,1.8)+path(`M${x+12} ${y-19}l5 29l9 6M${x} ${y}l17 10`,'none',C.gold,1);}
function stir(x,y){return path(`M${x-37} ${y}q36 25 72 0`,'none',C.blue,2)+arrow(x+27,y+7,x+35,y,C.blue);}
function detector(x,y,label='Detector'){return rect(x,y,76,97,'#e8f0f5',10)+rect(x+10,y+12,56,41,'#fcfeff',4)+lines(x+38,y+74,label,14,13);}
function sphere(kind){return rect(22,166,76,53,'#e8f0f5',8)+text(60,151,'Excitation',14)+arrow(103,192,141,192,C.gold)+circle(218,192,74,'#fcfeff',C.edge)+circle(218,192,58,'#f3f7fa',C.edge)+path('M180 224H254','none',C.edge,3)+(kind==='Bulk A crystals'?crystal(201,215):powder(200,218))+arrow(288,192,320,192,C.gold)+detector(320,146)+text(215,91,'Calibrated integrating sphere',19)+text(218,298,kind,16)+text(208,355,'Baseline → specimen measurement',15)+text(208,402,'Optical paths are explanatory',12,'middle',C.muted);}
function optics(label,film=false){return rect(20,135,93,90,'#e8f0f5',10)+lines(65,168,'Excitation / wavelength selection',16,14)+arrow(122,181,171,181,C.gold)+(film?rect(180,165,71,31,C.cream,3):rect(178,149,77,65,'#fcfeff',7))+text(216,237,'Specimen',14)+arrow(264,181,308,181,C.gold)+detector(309,135)+text(205,85,label,19)+rect(111,291,197,59,'#eef5fa',9)+text(210,316,film?'Film PL':'PL / PLE / decay',16)+text(210,339,'Source-scoped acquisition',12)+text(205,399,'No spectrum or decay curve is synthesized',12,'middle',C.muted);}
function draw(c){switch(c.art){
case 'dissolve':return vessel(23,91,71,88,'#f3f5f7')+powder(42,168,'#dae2e7')+lines(59,58,'C₁₂H₂₈NCl',15,16)+vessel(141,91,71,88,'#f3f5f7')+powder(160,168,'#dae2e7')+text(177,58,'SbCl₃',17)+vessel(284,91,70,88)+text(319,58,'DMF',17)+arrow(75,189,137,239)+arrow(177,189,161,239)+arrow(305,189,185,240)+vessel(118,249,92,104)+text(163,379,'Dissolve',15)+arrow(223,294,270,294)+path('M290 222H387L354 271V293H325V271Z','#fcfeff')+path('M303 237H374','none',C.blue,3)+vessel(312,303,58,69)+text(341,401,'Clear filtrate',14)+text(201,437,c.variant,14,'middle',C.muted);
case 'evaporate':return vessel(47,166,109,121)+arrow(168,227,233,227)+vessel(245,166,111,121,'#f7f3e5')+crystal(258,266)+crystal(300,266)+arrow(269,147,258,106)+arrow(319,147,330,106)+text(106,137,'Filtered precursor',15)+text(300,80,'Solvent evaporation',15)+text(298,325,'Collect bulk '+c.variant,18)+text(204,372,'Room temperature',18)+text(205,412,'Crystal habit and vessel shape are illustrative',12,'middle',C.muted);
case 'inject':return vessel(25,81,83,116)+text(67,58,'Full stock',17)+arrow(120,130,178,130)+rect(185,105,87,25,'#ecf4f9',3)+path('M186 105V93H194V105M272 118H307V187','none',C.edge,3)+text(229,88,'Aliquot transfer',14)+arrow(307,194,307,223)+vessel(242,235,129,113,C.cream)+stir(304,368)+powder(278,328)+vessel(43,271,94,87)+lines(90,245,'Toluene + oleic acid',19,15)+arrow(145,316,231,316)+text(206,404,'Rapid injection · vigorous stirring',15)+text(204,438,'No bath or reaction temperature is specified',12,'middle',C.muted);
case 'centrifuge':return vessel(30,141,82,117,C.cream)+powder(47,245)+text(71,118,'Crude product',15)+arrow(122,200,173,200)+rect(183,146,124,111,'#e8f0f5',16)+circle(245,201,37,'#fcfeff',C.edge)+[0,120,240].map(a=>{const t=a*Math.PI/180;return path(`M245 201L${245+28*Math.cos(t)} ${201+28*Math.sin(t)}`,'none',C.edge,5)}).join('')+text(246,283,'Centrifuge',16)+arrow(307,263,343,311)+path('M302 325H385L373 359H314Z','#e7edf1')+powder(325,342)+text(342,389,'Retain solid',15)+text(204,424,'No wash or drying procedure is supplied',12,'middle',C.muted);
case 'blend':return vessel(27,111,67,99,C.aqua)+powder(43,195,C.blue)+lines(61,70,'Blue phosphor',15,15)+vessel(164,111,67,99,C.cream)+powder(180,195,C.gold)+lines(198,70,'Yellow NCs',15,15)+vessel(301,111,67,99,'#eef2f6')+lines(334,70,'PS / toluene',15,15)+arrow(69,225,162,273)+arrow(198,225,198,273)+arrow(332,225,233,273)+vessel(149,279,99,88,'#e5edf1')+powder(169,349,C.blue)+powder(204,346,C.gold)+stir(199,384)+text(201,425,'Five separate mass-ratio formulations',14);
case 'cast-peel':return path('M46 80H103L116 95L63 110Z','#ecf4f9')+circle(85,142,5,C.cream)+arrow(84,153,84,187)+path('M29 211L140 188L166 210L53 234Z','#c8dbe5')+path('M46 211L133 197L149 210L60 224Z',C.cream)+text(100,267,'Cast on glass',15)+arrow(174,215,219,215)+rect(235,80,154,218,'#eff5f8',3)+path('M247 93H377V276H247Z','none',C.edge)+path('M259 117H365','none',C.edge,4)+path('M253 242H370','none',C.edge,3)+rect(275,233,79,6,C.cream,0)+arrow(299,212,299,160)+text(312,324,'Fume hood',16)+arrow(294,339,246,364)+path('M79 385L183 363L207 380L104 403Z','#c8dbe5')+path('M97 379Q137 341 181 346L231 360Q181 356 148 391Z',C.cream,C.gold)+text(299,385,'Peeled film',15)+text(299,409,'retained',14)+text(93,436,'Glass separates',12,'middle',C.muted);
case 'spin-anneal':return vessel(24,69,73,98)+text(61,46,'Precursor stock',15)+arrow(107,126,159,167)+rect(182,148,57,13,C.cream,2)+path('M151 180Q215 207 276 180V222Q215 251 151 222Z','#e6eff4')+path('M170 166Q216 139 262 166','none',C.blue,2)+arrow(252,157,263,166)+text(213,270,'Spin coat aliquot on glass',16)+arrow(214,283,214,310)+rect(163,337,99,7,'#bcd2df',1)+rect(169,331,88,5,C.cream,1)+[183,212,242].map(x=>path(`M${x} 371q-7 -8 0 -16q7 -7 0 -13`,'none',C.gold,2)).join('')+text(213,402,'Then anneal the supported film',15)+text(209,434,'No PS/phosphor blending or peeling',12,'middle',C.muted);
case 'diffraction':return rect(24,91,358,128,'#f1f6f9',10)+text(75,125,'PXRD',17)+rect(154,155,65,8,C.cream,1)+arrow(98,143,152,157,C.gold)+arrow(221,157,295,140,C.gold)+detector(302,112,'Detector')+rect(24,262,358,132,'#f8f5ea',10)+text(75,296,'SCXRD',17)+crystal(185,335)+arrow(101,327,178,327,C.gold)+arrow(215,327,294,310,C.gold)+detector(302,282,'Detector')+text(204,56,'Separate diffraction acquisitions',19)+text(202,434,'No synthetic reflections or phase assignment',12,'middle',C.muted);
case 'xps-tga':return rect(24,102,163,232,'#eef4f8',13)+text(105,80,'XPS',20)+rect(53,169,105,68,'#fcfeff',8)+rect(77,214,59,5,C.cream,1)+arrow(78,143,99,185,C.gold)+arrow(119,186,157,154,C.gold)+lines(105,285,'Photoelectron analysis',19,15)+rect(220,102,163,232,'#fbf6e9',13)+text(302,80,'TGA',20)+path('M272 155H334M302 155V217M273 217H331','none',C.edge,2)+powder(286,212)+path('M258 241H346','none',C.gold,3)+arrow(362,155,339,202,C.blue)+text(355,139,'N₂',17)+lines(302,285,'Thermogravimetry under N₂',19,15)+text(201,389,'N₂ applies only to TGA',18)+text(201,429,'XPS atmosphere / pressure not specified',12,'middle',C.muted);
case 'optics':return optics(c.variant);
case 'sphere':return sphere(c.variant);
case 'tem':return rect(149,85,102,257,'#e8f0f5',17)+circle(200,116,13,'#fcfeff',C.edge)+path('M186 136L200 200L214 136','none',C.blue,2)+rect(154,211,92,7,C.cream,1)+path('M174 226L200 294L226 226','none',C.blue,2)+rect(167,304,66,14,'#b4cad7',3)+lines(70,147,'Electron beam',16,15)+arrow(107,156,158,177)+lines(325,227,'NC specimen',17,15)+text(201,380,'FEI Tecnai G2 F30 · EFTEM',17)+text(201,421,'Grid and deposition method are unspecified',12,'middle',C.muted);
case 'film-optics':return optics('Composite and spin-coated films',true);
case 'beta':return rect(22,117,138,121,'#e8f0f5',14)+lines(91,154,'Linear electron accelerator',18,17)+arrow(173,173,220,173,C.gold)+path('M232 130L250 148L245 190L227 176Z',C.cream,C.gold)+rect(225,227,70,12,C.cream,1)+lines(261,279,'Bulk A crystal / NC composite film',22,14)+path('M293 185Q337 133 369 187V275','none',C.blue,3)+detector(323,289,'Fibre optics')+text(95,302,'Electron excitation',15)+text(194,381,'Radioluminescence acquisition',17)+text(204,422,'Exact composite blend ratio is unidentified',12,'middle',C.muted);
case 'dft':return rect(39,89,332,227,'#e9f1f7',14)+rect(54,105,302,187,'#fcfeff',6)+text(205,136,'VASP · PAW',20)+rect(73,159,115,83,'#eff5f8',8)+rect(220,159,115,83,'#fcf6e8',8)+text(131,188,'Compound A',16)+text(277,188,'Compound B',16)+text(131,217,'PBE / HSE06',13)+text(277,217,'PBE / HSE06',13)+path('M167 318V344H242V318','none',C.edge,3)+text(206,378,'Relax lattice and atomic positions',16)+text(206,422,'Calculation context; no invented coordinate model',12,'middle',C.muted);
default:throw Error('Unmapped Lian stage '+c.art);
}}
function quantity(q){if(!q)return 'Not reported';const v=quantityValue(q),unit=({degC:'°C',angstrom:'Å',uL:'µL',um:'µm',count:'',day:'days','eV/angstrom':'eV/Å'})[q.unit]??q.unit??'';if(v===null)return q.raw_text||'Not reported';return `${q.approximate?'≈ ':''}${v}${unit?' '+unit:''}`;}
export function buildLian2021Scene(o,r){
 if(r?.lineage?.source_group!=='lian2021')return null;const c=DATA.configs[o?.id];if(!c||c.record_id!==r.record_id)return null;
 const rows=Object.entries(o.parameters||{}).map(([k,q])=>({label:DATA.parameter_labels[k]||k.replaceAll('_',' '),value:quantity(q),pointer:c.operation_pointer+'/parameters/'+k,quantity:q,kind:'operation_parameter'}));
 for(const m of c.measurement_rows){const actual=r.measurements?.find(v=>v.id===m.measurement_id);if(!actual)throw Error('Missing context '+m.measurement_id);rows.push({label:m.label,value:quantity(actual.value),pointer:m.pointer,quantity:actual.value,kind:'source_context'});}
 rows.push(...c.notes.map(n=>({...n,kind:'source_scope_note'})));
 if(c.art!=='dft')rows.push({label:'Atmosphere / pressure',value:o.id==='bulk-xps-tga'?'N₂ for TGA only; flow and pressure are not reported.':'No specified gas atmosphere or numeric pressure for this stage.',kind:'missingness'});
 const caption='Source-specific explanatory diagram. Apparatus geometry, crystal/powder symbols and colors are schematic; measured images and structure data remain separate.';
 const art=draw(c),artSvg=`<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 20 405 450" role="img" aria-label="${esc(c.title)}"><title>${esc(c.title)}</title><desc>${esc(caption)}</desc>${art}</svg>`;
 let y=130,panel='';for(const row of rows){const labelLines=wrap(row.label,62),valueLines=wrap(row.value,55);panel+=labelLines.map((s,i)=>text(430,y+i*16,s,12,'start',C.muted,600)).join('');y+=labelLines.length*16+6;panel+=valueLines.map((s,i)=>text(430,y+i*19,s,14,'start')).join('');y+=valueLines.length*19+20;}
 const divider=Math.max(568,y+4),note=wrap(c.prose,116),height=divider+76+note.length*19;
 const svg=`<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 930 ${height}" role="img" aria-label="${esc(c.title)}"><title>${esc(c.title)}</title><desc>${esc(caption)}</desc><rect width="930" height="${height}" rx="16" fill="#fff"/>${text(28,36,c.title,22,'start',C.ink,600)}${text(28,68,'SYNTHESIS PROTOCOL / EXPERIMENTAL CONTEXT',11,'start',C.muted)}<g transform="translate(0,86)">${art}</g>${rect(408,96,497,divider-110,'#f2f7fa',12,'#dce8ef')}${panel}${path(`M27 ${divider}H903`,'none','#d9e5ec',1)}${note.map((s,i)=>text(28,divider+28+i*19,s,14,'start')).join('')}${text(28,height-18,'Geometry is explanatory; no source atomic coordinates, spectrum or micrograph is synthesized.',11,'start',C.muted)}</svg>`;
 return {kind:r.record_id+'--'+o.id,title:c.title,description:c.prose,caption,rows,svg,artSvg};
}
export function createLian2021Art(o,r){const s=buildLian2021Scene(o,r);if(!s)return null;const h=document.createElement('div');h.className='protocol-art protocol-art-lian2021';h.dataset.scene=s.kind;h.style.height='auto';h.innerHTML=s.artSvg;h.querySelector('svg').style.cssText='display:block;width:100%;height:auto;max-height:none';return h;}
export function createLian2021ConditionGrid(o,r){const s=buildLian2021Scene(o,r);if(!s)return null;const dl=document.createElement('dl');dl.className='protocol-condition-grid';for(const row of s.rows){const d=document.createElement('div'),dt=document.createElement('dt'),dd=document.createElement('dd');dt.textContent=row.label;dd.textContent=row.value;d.append(dt,dd);dl.append(d);}return dl;}
export function renderLian2021Markup(s){return `<style>.lian-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(100%,290px),1fr));gap:20px;align-items:start}.lian-art svg{display:block;width:100%;height:auto}.lian-conditions{background:#f2f7fa;border:1px solid #dce8ef;border-radius:12px;padding:20px;margin:0}.lian-conditions dt{margin-top:14px;font-size:12px;color:#60788a;line-height:1.5}.lian-conditions dt:first-child{margin-top:0}.lian-conditions dd{margin:4px 0 0;font-size:15px;line-height:1.55;overflow-wrap:anywhere;color:#173a50}.lian-note{font-size:15px;line-height:1.65}.lian-caption{font-size:12px;line-height:1.6;color:#60788a}</style><div class="lian-grid"><div class="lian-art">${s.artSvg}</div><dl class="lian-conditions">${s.rows.map(x=>`<dt>${esc(x.label)}</dt><dd>${esc(x.value)}</dd>`).join('')}</dl></div><p class="lian-note">${esc(s.description)}</p><p class="lian-caption">${esc(s.caption)}</p>`;}
export const lian2021SceneSelection={source_group:'lian2021',records:Object.fromEntries([...new Set(Object.values(DATA.configs).map(c=>c.record_id))].map(id=>[id,Object.entries(DATA.configs).filter(([k,c])=>c.record_id===id).map(([k])=>k)]))};
